<div class="section-heading"><div><h2><?= e(t('Project pages')) ?></h2><p class="muted"><?= e(t('Capture ideas and decisions, then turn them into linked work items.')) ?></p></div><a class="btn" href="#work-new-page"><?= e(t('+ Page')) ?></a></div><?php if(!$pages): ?><section class="card empty"><h3><?= e(t('A place for the thinking behind the work.')) ?></h3><p><?= e(t('Create a project page. Every save keeps its previous version.')) ?></p></section><?php else: ?><div class="website-grid"><?php foreach($pages as $projectPage): ?><article class="card"><span class="website-kicker"><?= $projectPage['pinned']?t('PINNED PAGE'):t('PROJECT NOTE') ?></span><h2><a href="<?= $workPath ?>/page/<?= e($projectPage['id']) ?>"><?= e($projectPage['title']) ?></a></h2><p class="work-page-excerpt"><?= e(mb_strimwidth($projectPage['body'],0,180,'…')) ?></p><p class="footnote">v<?= e($projectPage['version']) ?> <?= e(t('· Updated')) ?> <?= e($projectPage['updated_at']) ?></p></article><?php endforeach; ?></div><?php endif; ?>
<section class="card" id="work-new-page"><h2><?= e(t('Create a page')) ?></h2><form class="form-grid" method="post" action="<?= $workPath ?>/pages"><?= csrf_field() ?><label class="full"><?= e(t('Title')) ?><input name="title" maxlength="200" required></label><label class="full"><?= e(t('Page content')) ?><textarea name="body" maxlength="60000" rows="8" data-work-markdown></textarea></label><label class="work-checkbox full"><input type="checkbox" name="pinned" value="1"> <?= e(t('Pin this page')) ?></label><div class="full"><button><?= e(t('Create page')) ?></button></div></form></section>
<?php $trashedPages=Db::all('SELECT * FROM work_pages WHERE project_id=? AND deleted_at IS NOT NULL ORDER BY deleted_at DESC',[$project['id']]);if($trashedPages): ?><details class="card"><summary><?= e(t('Page trash ·')) ?> <?= count($trashedPages) ?></summary><?php foreach($trashedPages as $projectPage): ?><article class="studio-record-row"><strong><?= e($projectPage['title']) ?></strong><form method="post" action="<?= $workPath ?>/page/<?= e($projectPage['id']) ?>/trash"><?= csrf_field() ?><input type="hidden" name="version" value="<?= e($projectPage['version']) ?>"><input type="hidden" name="restore" value="1"><button class="secondary"><?= e(t('Restore page')) ?></button></form></article><?php endforeach; ?></details><?php endif; ?>
